/**
 * Fitness: docs/BACKLOG-SUMMARY.md matches docs/BACKLOG.md.
 *
 * The summary is generated by `scripts/backlog-summary.sh` and must be rerun
 * with every backlog edit (rule in docs/BACKLOG.md). This makes `pnpm test`,
 * and with it the full gate, fail on a stale summary.
 */
import { execFileSync } from 'node:child_process'
import path from 'node:path'
import { describe, expect, it } from 'vitest'

const ROOT = path.resolve(import.meta.dirname, '../..')

describe('backlog summary', () => {
  it('is up to date (run `pnpm backlog:summary`)', () => {
    const check = () =>
      execFileSync('scripts/backlog-summary.sh', ['--check'], { cwd: ROOT, stdio: 'pipe', timeout: 10_000 })
    expect(check).not.toThrow()
  })
})
